bridge.help:
Usage: bridge [ OPTIONS ] OBJECT { COMMAND | help }
       bridge [ -force ] -batch filename
where  OBJECT := { link | fdb | mdb | mst | vlan | vni | monitor }
       OPTIONS := { -V[ersion] | -s[tatistics] | -d[etails] |
                    -o[neline] | -t[imestamp] | -n[etns] name |
                    -com[pressvlans] -c[olor] -p[retty] -j[son] }

dcb.help:
Usage: dcb [ OPTIONS ] OBJECT { COMMAND | help }
       dcb [ -f | --force ] { -b | --batch } filename [ -n | --netns ] netnsname
where  OBJECT := { app | apptrust | buffer | dcbx | ets | maxrate | pfc | rewr }
       OPTIONS := [ -V | --Version | -i | --iec | -j | --json
                  | -N | --Numeric | -p | --pretty
                  | -s | --statistics | -v | --verbose]

